import Foundation
struct CommunityPost:Codable {let source:String,id:String,title:String,url:String;let published_ms:Int64}
struct CommunityDataset {let posts:[CommunityPost];let synthetic:Bool;let collected:Int64;let origin:String}
struct CommunityAnalysis {let dataset:CommunityDataset,symbol:String,hours:Int64,now:Int64;var posts:[CommunityPost]=[];var up=0,down=0,mixed=0,neutral=0,duplicates=0,outside=0,irrelevant=0;var sources:[String:Int]=[:],mentions:[String:Int]=[:]}
enum CommunityCore {
 static let dcList="https://gall.dcinside.com/board/lists/?id=bitcoins_new1"
 static let symbols=["전체","BTC","ETH","XRP","SOL","DOGE","ADA"]
 static let aliases=[["비트코인","bitcoin","btc"],["이더리움","ethereum","eth"],["리플","xrp"],["솔라나","solana","sol"],["도지코인","dogecoin","doge"],["에이다","cardano","ada"]]
 static let up=["상승","급등","반등","호재","돌파","불장","떡상"],down=["하락","급락","악재","폭락","해킹","사기","떡락"]
 static func safeURL(_ source:String,_ raw:String)->Bool{guard let u=URLComponents(string:raw),u.scheme?.lowercased()=="https",u.user==nil,u.password==nil,u.fragment==nil,u.port==nil || u.port==443,let host=u.host?.lowercased()else{return false};if source=="COINPAN"{return ["coinpan.com","www.coinpan.com"].contains(host)};return source=="DCINSIDE" && host=="gall.dcinside.com" && u.path=="/board/view/" && (u.percentEncodedQuery?.range(of:"^id=bitcoins_new1&no=[0-9]{1,20}$",options:.regularExpression) != nil)}
 static func valid(_ p:CommunityPost)->Bool{["DCINSIDE","COINPAN"].contains(p.source) && p.id.range(of:"^[A-Za-z0-9_-]{1,80}$",options:.regularExpression) != nil && !p.title.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty && p.title.unicodeScalars.count<=300 && p.published_ms>0 && (p.url.isEmpty || safeURL(p.source,p.url))}
 static func parse(_ data:Data,_ now:Int64)throws->CommunityDataset{guard data.count<=1048576 else{throw StrategyError.invalid("JSON 1MB 이하 필요")};struct Input:Decodable{let community_schema_version:Int,synthetic:Bool,collected_ms:Int64,posts:[CommunityPost]};let input=try JSONDecoder().decode(Input.self,from:data);guard input.community_schema_version==1,input.collected_ms>0,input.collected_ms<=now,input.posts.count<=1000,input.posts.allSatisfy(valid)else{throw StrategyError.invalid("출처·ID·제목·시간·링크/schema1 확인 필요")};return CommunityDataset(posts:input.posts,synthetic:input.synthetic,collected:input.collected_ms,origin:"가져온 파일 · 출처 미검증")}
 static func group(_ pattern:String,_ text:String)->String?{guard let re=try? NSRegularExpression(pattern:pattern,options:[.dotMatchesLineSeparators]),let m=re.firstMatch(in:text,range:NSRange(text.startIndex...,in:text)),m.numberOfRanges>1,let range=Range(m.range(at:1),in:text)else{return nil};return String(text[range])}
 static func plain(_ text:String)->String{var s=text.replacingOccurrences(of:"<[^>]*>",with:"",options:.regularExpression);for (a,b) in [("&nbsp;"," "),("&lt;","<"),("&gt;",">"),("&quot;","\""),("&#39;","'")]{s=s.replacingOccurrences(of:a,with:b)};if let re=try? NSRegularExpression(pattern:"&#(x[0-9A-Fa-f]+|[0-9]+);"){for m in re.matches(in:s,range:NSRange(s.startIndex...,in:s)).reversed(){guard let full=Range(m.range,in:s),let num=Range(m.range(at:1),in:s)else{continue};let n=String(s[num]);let value=UInt32(n.hasPrefix("x") ? String(n.dropFirst()):n,radix:n.hasPrefix("x") ? 16:10);s.replaceSubrange(full,with:value.flatMap(UnicodeScalar.init).map(String.init) ?? " ")}};return s.replacingOccurrences(of:"&amp;",with:"&").trimmingCharacters(in:.whitespacesAndNewlines)}
 static func dcHTML(_ html:String,_ now:Int64)throws->CommunityDataset{guard html.utf8.count<=2097152 else{throw StrategyError.invalid("응답 2MB 초과")};let re=try NSRegularExpression(pattern:"<tr\\b[^>]*>.*?</tr>",options:[.dotMatchesLineSeparators]);let date=DateFormatter();date.locale=Locale(identifier:"en_US_POSIX");date.timeZone=TimeZone(identifier:"Asia/Seoul");date.dateFormat="yyyy-MM-dd HH:mm:ss";date.isLenient=false;var posts:[CommunityPost]=[]
 for m in re.matches(in:html,range:NSRange(html.startIndex...,in:html)){if posts.count>=100{break};guard let range=Range(m.range,in:html)else{continue};let row=String(html[range]);guard let id=group("data-no=['\"]([0-9]+)['\"]",row),let cell=group("<td[^>]*class=['\"][^'\"]*gall_tit[^'\"]*['\"][^>]*>(.*?)</td>",row),let time=group("<td[^>]*class=['\"][^'\"]*gall_date[^'\"]*['\"][^>]*title=['\"]([^'\"]+)['\"]",row),let title=group("<a\\b[^>]*href=['\"][^'\"]*(?:/board/view/|\\?id=bitcoins_new1)[^'\"]*['\"][^>]*>(.*?)</a>",cell),let at=date.date(from:time)else{continue};let p=CommunityPost(source:"DCINSIDE",id:id,title:plain(title),url:"https://gall.dcinside.com/board/view/?id=bitcoins_new1&no="+id,published_ms:Int64(at.timeIntervalSince1970*1000));if valid(p){posts.append(p)}}
 guard !posts.isEmpty else{throw StrategyError.invalid("목록 구조 변경 또는 접근 제한 · 분석 불가")};return CommunityDataset(posts:posts,synthetic:false,collected:now,origin:"디시 비트코인 갤러리 · 최신 목록 1페이지")}
 static func mentions(_ title:String,_ index:Int)->Bool{let lower=title.lowercased();return aliases[index].contains{a in if a.range(of:"^[a-z]+$",options:.regularExpression) != nil{return lower.range(of:"(?<![a-z0-9])"+a+"(?![a-z0-9])",options:.regularExpression) != nil};return lower.contains(a)}}
 static func analyze(_ d:CommunityDataset,_ symbol:String,_ hours:Int64,_ now:Int64)->CommunityAnalysis{var a=CommunityAnalysis(dataset:d,symbol:symbol,hours:hours,now:now);var ids=Set<String>(),titles=Set<String>();for p in d.posts.sorted(by:{$0.published_ms>$1.published_ms}){if p.published_ms>now || p.published_ms<now-hours*3600000{a.outside+=1;continue};let normalized=p.title.lowercased().replacingOccurrences(of:"[^\\p{L}\\p{N}]",with:"",options:.regularExpression);if !ids.insert(p.source+":"+p.id).inserted || (!normalized.isEmpty && !titles.insert(normalized).inserted){a.duplicates+=1;continue};let relevant=(0..<aliases.count).contains{mentions(p.title,$0) && (symbol=="전체" || symbol==symbols[$0+1])};if !relevant{a.irrelevant+=1;continue};a.posts.append(p);a.sources[p.source,default:0]+=1;for i in 0..<aliases.count where mentions(p.title,i){a.mentions[symbols[i+1],default:0]+=1};let u=up.contains{p.title.contains($0)},v=down.contains{p.title.contains($0)};if u && v{a.mixed+=1}else if u{a.up+=1}else if v{a.down+=1}else{a.neutral+=1}};return a}
 static func summary(_ a:CommunityAnalysis)->String{let collected=Date(timeIntervalSince1970:Double(a.dataset.collected)/1000).formatted(date:.numeric,time:.standard);return (a.dataset.synthetic ? "합성 예제 · 실제 커뮤니티 자료 아님\n":"")+a.dataset.origin+"\n수집 \(collected)\n\(a.symbol) · 최근 \(a.hours)시간 · 분석 제목 \(a.posts.count)개\n상승 표현 \(a.up) · 하락 표현 \(a.down) · 혼합 \(a.mixed) · 해당 표현 없음 \(a.neutral)\n출처별 \(a.sources)\n종목 언급 \(a.mentions)\n동일 ID/제목 제외 \(a.duplicates) · 기간 밖/미래 \(a.outside) · 종목 미일치 \(a.irrelevant)\n제목 키워드 집계이며 감성·투자 심리 판정이 아닙니다. 반어·부정 표현·은어를 이해하지 못합니다. 작은 표본과 최신 목록은 전체 여론을 대표하지 않습니다."}
 static func report(_ a:CommunityAnalysis)throws->Data{let j:[String:Any]=["mode":"COMMUNITY_TITLE_RESEARCH_ONLY","schema_version":1,"synthetic":a.dataset.synthetic,"origin":a.dataset.origin,"collected_ms":a.dataset.collected,"analyzed_ms":a.now,"symbol":a.symbol,"window_hours":a.hours,"sample_count":a.posts.count,"up_expressions":a.up,"down_expressions":a.down,"mixed":a.mixed,"no_expression":a.neutral,"duplicates_removed":a.duplicates,"outside_window":a.outside,"unmatched":a.irrelevant,"source_counts":a.sources,"symbol_mentions":a.mentions,"trading_signal":false];return try JSONSerialization.data(withJSONObject:j,options:[.prettyPrinted,.sortedKeys])}
 static func sample(_ now:Int64)->CommunityDataset{CommunityDataset(posts:[CommunityPost(source:"COINPAN",id:"sample1",title:"비트코인 상승 호재",url:"",published_ms:now-3600000),CommunityPost(source:"DCINSIDE",id:"sample2",title:"이더리움 하락 악재",url:"",published_ms:now-7200000),CommunityPost(source:"COINPAN",id:"sample3",title:"리플 상승과 하락",url:"",published_ms:now-10800000)],synthetic:true,collected:now,origin:"합성 예제")}
}
